/// <summary>
/// CB718 VM Task - 162235 Std code from Microsoft for logging
/// </summary>
internal static final class METApplicationInsightsEventIds
{
    internal static const str EventDefault          = '1'; // eventId to indicate default event id
    internal static const str DMFLogging            = '2'; // eventId to indicate DMF logging
    internal static const str DMFLedgerJournalPost  = '3'; // eventId to indicate Journal posting
    internal static const str DMFBatchLogging       = '4'; // eventId to indicate Batch Logging
}
